#!/usr/bin/env python3
"""Results JSON files se README ke auto-generated blocks regenerate karta hai.

Blocks:
  <!-- TMU-VS-BASELINE:START --> ... <!-- TMU-VS-BASELINE:END -->
  <!-- TMU-TRANSPLANT:START --> ... <!-- TMU-TRANSPLANT:END -->

Example:
    python scripts/update_readme_results.py \
        --comparison results/tmu_vs_baseline.json \
        --transplant results/transplant_test.json
"""

from __future__ import annotations

import argparse
import json
import os
import sys
from typing import Dict, List

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "src"))
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from train_comparison import markdown_section, update_readme  # noqa: E402

from tmu.transplant import format_transplant_report  # noqa: E402


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser(description="Regenerate README result blocks from JSON results")

    p.add_argument("--readme", type=str, default="README.md")
    p.add_argument("--comparison", type=str, default="results/tmu_vs_baseline.json")
    p.add_argument("--transplant", type=str, default="results/transplant_test.json")

    return p.parse_args()


def transplant_section(res: Dict) -> str:
    lines: List[str] = []
    lines.append("## \U0001F52C Transplant Test: Plain GPT-2 vs GPT-2 + TMU Layer")
    lines.append("")
    lines.append(
        "_Auto-generated by 'Transplant Test' workflow ("
        + str(res.get("meta", {}).get("generated_at", "n/a"))
        + "). Source: "
        + str(res.get("results_path", "results/transplant_test.json"))
        + "_"
    )
    lines.append("")
    lines.append(format_transplant_report(res))
    lines.append("")

    coherence = res.get("coherence")
    if coherence:
        lines.append("### Time coherence (TMU layer ke saath)")
        lines.append("")
        lines.append("| Period | MAD | Cosine | Argmax agree |")
        lines.append("|---|---|---|---|")
        for key in ("period_86400s", "period_43200s", "period_604800s", "period_31536000s"):
            c = coherence.get(key)
            if not c:
                continue
            lines.append(
                f"| {key} | {c.get('mad', 0.0):.4f} | {c.get('cos', 0.0):.5f} | {c.get('agree', 0.0):.4f} |"
            )
        lines.append("")

    lines.append("### Interpretation")
    lines.append("")
    lines.append(
        "- **Time sensitivity**: baseline GPT-2 ko time input milta hi nahi, isliye uska "
        "logit change 0 hai. TMU layer wale model ke logits time shift par badalte hain — "
        "matlab layer time signal ko model tak sach me pahuncha rahi hai."
    )
    lines.append(
        "- **Quality**: eval loss/perplexity compare karke dekho ki layer ne LM fit kitna "
        "improve kiya."
    )
    lines.append(
        "- **Cost**: sirf TMU layer train hoti hai, base GPT-2 frozen rehta hai."
    )
    lines.append("")

    return "\n".join(lines)


def update_block(readme_path: str, start: str, end: str, section: str) -> None:
    p = readme_path
    text = open(p, encoding="utf-8").read() if os.path.exists(p) else ""

    block = start + "\n" + section + end

    if start in text and end in text:
        i = text.index(start)
        j = text.index(end) + len(end)
        text = text[:i] + block + text[j:]
    else:
        text = text.rstrip() + "\n\n" + block + "\n"

    open(p, "w", encoding="utf-8").write(text)


def main() -> None:
    args = parse_args()

    if os.path.exists(args.comparison):
        with open(args.comparison, "r", encoding="utf-8") as f:
            comp = json.load(f)
        update_readme(args.readme, markdown_section(comp))
        print("Comparison block updated:", args.readme)
    else:
        print("Skipped (missing):", args.comparison)

    if os.path.exists(args.transplant):
        with open(args.transplant, "r", encoding="utf-8") as f:
            tr = json.load(f)
        tr.setdefault("results_path", args.transplant)
        update_block(
            args.readme,
            "<!-- TMU-TRANSPLANT:START -->",
            "<!-- TMU-TRANSPLANT:END -->",
            transplant_section(tr),
        )
        print("Transplant block updated:", args.readme)
    else:
        print("Skipped (missing):", args.transplant)


if __name__ == "__main__":
    main()
